WITH enriched AS (SELECT *, NTILE(5) OVER w_grp AS salary_bucket, DENSE_RANK() OVER w_recent AS salary_dense_rank, LAST_VALUE(job_title, TRUE) OVER w_part AS last_known_job_title FROM employees WINDOW w_grp AS (PARTITION BY manager_id ORDER BY salary DESC, id), w_recent AS (ORDER BY salary), w_part AS (PARTITION BY dept_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, full_name, email, dept_id, manager_id, is_remote, level, salary_dense_rank, last_known_job_title FROM enriched ORDER BY manager_id DESC
